select set_config('lumiscore.catalog_release_receipt','{"rows":[{"key":{"id":987215001},"seq":1,"relation":"editions","after_row":{"id":987215001,"title":"Gullivers reizen","isbn_10":"9027491259","isbn_13":"9789027491251","work_id":987115001,"cover_id":null,"language":"dut","publisher":"Het Spectrum","publish_date":null,"open_library_edition_id":"OL24354314M"},"before_row":{"id":987215001,"title":"Gullivers reizen","isbn_10":"9027491259","isbn_13":null,"work_id":987115001,"cover_id":null,"language":"dut","publisher":"Het Spectrum","publish_date":null,"open_library_edition_id":"OL24354314M"}},{"key":{"work_id":987115001,"language":"nl"},"seq":2,"relation":"catalog_work_descriptions","after_row":{"text":"Lemuel Gulliver beschrijft reizen die hem telkens buiten zijn vertrouwde wereld brengen. Hij belandt onder meer tussen uitzonderlijk kleine mensen, in een rijk van reuzen en op een vliegend eiland. De gebruiken van deze samenlevingen dwingen hem zijn eigen maatstaven te herzien. Wat als een avontuurlijk reisverslag begint, wordt zo ook een onderzoek naar menselijke ijdelheid, macht en zogenaamd verstandige instellingen. Swift gebruikt de botsing tussen Gulliver en zijn gastheren als satire op zijn eigen samenleving.","work_id":987115001,"evidence":[{"note":"Exact existing1979Spectrumhardcover, ArjaanvanNimwegen translation. KB binds original four-part title, exact translator and269p, distinct from abridged youth/first-two-parts editions. AuthorSwift, not translator. Reuse existing Work1395/edition1440 and fill only absent ISBN; no duplicate edition.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p801594057"],"reference":"work:1395","checked_at":"2026-11-02T21:24:43.768Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-020.json","sources":["https://www.boekenplatform.nl/gullivers-reizen-63669","https://www.boekwinkeltjes.nl/v/lammegoedzak/page/67/?sort=nr0","https://ope